<?php use App\Support\Ui; ?>
<div class="page-heading admin-heading"><div><span class="eyebrow">LIVE OPERATIONS</span><h1>Good <?= (int)$now->format('H')<12?'morning':((int)$now->format('H')<17?'afternoon':'evening') ?></h1><p><?= $e($now->format('l, d F Y · g:i A')) ?> IST</p></div><a class="button primary" href="<?= $e($url('admin/interview/new')) ?>"><?= Ui::icon('plus') ?>New interview</a></div>
<section class="ops-metrics" aria-label="Today at a glance"><?php foreach([['Today',$metrics['today'],'calendar'],['Tool',$metrics['tool'],'monitor'],['Normal',$metrics['normal'],'briefcase'],['Remaining',$metrics['remaining'],'clock'],['Resources free now',$metrics['available'],'check']] as [$label,$value,$icon]): ?><article><span><?= Ui::icon($icon) ?><?= $e($label) ?></span><strong><?= $e($value) ?></strong></article><?php endforeach; ?></section>
<div class="command-grid"><section class="card"><div class="card-heading"><div><h2>Today’s schedule</h2><p>Only interviews starting today in Asia/Kolkata.</p></div><a class="text-link" href="<?= $e($url('admin/calendar')) ?>">Open calendar →</a></div><?php if(!$rows): ?><div class="empty-state"><div class="empty-icon"><?= Ui::icon('calendar') ?></div><h3>No interviews scheduled for today.</h3><p>Future bookings remain available in Calendar and Interviews.</p></div><?php else: ?><div class="agenda-list"><?php foreach($rows as $item): ?><a href="<?= $e($url('admin/interview?id='.$item['id'])) ?>" class="agenda-row <?= $item['end_local']<$now?'elapsed':'' ?>"><time><?= $e($item['start_local']->format('g:i A')) ?></time><span class="agenda-line"></span><?= Ui::candidateAvatar($item,'agenda-avatar') ?><div><strong><?= $e($item['candidate_name']) ?><?php if($item['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></strong><small><?= $e($item['company_name']) ?> · <?= $e($item['job_role']) ?> · <?= $e($item['technology_name']) ?> · <?= $e($item['resource_name']) ?><?= $item['support_person_name']?' · '.$e($item['support_person_name']):'' ?></small></div><span class="badge <?= $item['interview_type']==='TOOL'?'purple':'neutral' ?>"><?= $e(ucfirst(strtolower($item['interview_type']))) ?></span></a><?php endforeach; ?></div><?php endif; ?></section>
<aside class="now-next"><article class="card focus-card"><span class="eyebrow">HAPPENING NOW</span><?php if($current): ?><div class="focus-candidate"><?= Ui::candidateAvatar($current,'focus-avatar') ?><div><h2><?= $e($current['candidate_name']) ?></h2><?php if($current['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></div></div><p><?= $e($current['company_name']) ?> · <?= $e($current['display_time']) ?></p><strong><?= $e($current['resource_name']) ?></strong><a class="text-link" href="<?= $e($url('admin/interview?id='.$current['id'])) ?>">View booking →</a><?php else: ?><h2>No live interview</h2><p>No interview from today’s schedule is happening now.</p><?php endif; ?></article><article class="card focus-card"><span class="eyebrow">UP NEXT TODAY</span><?php if($next): ?><div class="focus-candidate"><?= Ui::candidateAvatar($next,'focus-avatar') ?><div><h2><?= $e($next['candidate_name']) ?></h2><?php if($next['candidate_deleted']):?><span class="deleted-label">Deleted candidate</span><?php endif;?></div></div><p><?= $e($next['start_local']->format('g:i A')) ?> · <?= $e($next['company_name']) ?></p><strong><?= $e($next['resource_name']) ?></strong><?php else: ?><h2>Nothing else today</h2><p>The remaining schedule for today is clear.</p><?php endif; ?></article></aside></div>
